func freeBoardCountries() []string {
	raw := strings.TrimSpace(os.Getenv("FREE_BOARD_COUNTRIES"))
	if raw == "" {
		return []string{"germany", "netherlands"}
	}
	parts := strings.Split(raw, ",")
	out := make([]string, 0, len(parts))
	seen := map[string]bool{}
	for _, part := range parts {
		key := strings.ToLower(strings.TrimSpace(part))
		if key == "" || seen[key] {
			continue
		}
		seen[key] = true
		out = append(out, key)
	}
	if len(out) == 0 {
		return []string{"germany", "netherlands"}
	}
	return out
}

