export async function fetchCompanyRoles({ country, company, offset = 0 } = {}) {
  const params = boardQueryParams({ page: 1, pageSize: 25 });
  params.set("company_country", country);
  params.set("company", company);
  params.set("offset", String(offset));
  const prefix = panelApiPrefix();
  const res = await apiFetch(`${prefix}/board/company-roles?${params.toString()}`, {
    cache: "no-store",
  });
  const data = await parseJsonResponse(res);
  if (!res.ok) {
    const msg = data.error || "Could not load more roles";
    toast(msg);
    throw new Error(msg);
  }
  return data;
}

export async function unlockNextMatchedRole({ country, company, url, idempotencyKey = "", title = "" } = {}) {
  const res = await apiFetch("/api/jobs/unlock-role", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      country,
      company,
      url,
      idempotency_key: idempotencyKey,
      title,
    }),
  });
  const data = await parseJsonResponse(res);
  if (!res.ok) {
    const msg = data.error || "Could not unlock the next role";
    toast(msg);
    const err = new Error(msg);
    err.status = res.status;
    err.data = data;
    throw err;
  }
  return data;
}

